    "translation": "(എതിരാളി പറയുന്നു): വേദങ്ങൾ അടുത്ത കാലത്തുള്ളതാണെന്ന് ചിലർ കരുതുന്നു — കാരണം അവ മനുഷ്യരുടെ പേരുകളിലാണ് അറിയപ്പെടുന്നത്.",
    "commentary": "ഈ അധ്യായത്തിന്റെ അവസാന വിഷയം (വേദാപൗരുഷേയത്വാധികരണം) — വേദത്തിന്റെ കർത്താവില്ലായ്മയെ പ്രതിരോധിക്കുന്നത് — ആരംഭിക്കുന്നു. വേദത്തിന്റെ പ്രത്യേക ശാഖകൾ മാനുഷിക ഋഷിമാരുടെ പേരുകളിൽ വ്യക്തമായി അറിയപ്പെടുന്നു — 'കാഠകം' (കഠ ഋഷിയുടെ പേരിൽ), 'തൈത്തിരീയം' പോലെ. വേദം ശാശ്വതവും കർത്താവില്ലാത്തതുമാണെങ്കിൽ മർത്യരുടെ പേരുകൾ എന്തിന്?",
