    "commentary": "ഒന്നാം അധ്യായം ഒന്നാം പാദം അവസാനിപ്പിക്കുന്ന ഈ അവസാന സൂത്രം തർക്ക (വാദപ്രതിവാദ) ഭാഗം സമാപിക്കുന്നു. വേദഭാഗം ചരിത്ര വിവരണമോ കഥയോ (അർത്ഥവാദം) പോലെ തോന്നിയാലും അതിന്റെ യഥാർത്ഥ ഘടനാപരമായ ഉദ്ദേശ്യം ചരിത്രം പഠിപ്പിക്കലല്ലെന്ന് ജൈമിനി സ്ഥാപിക്കുന്നു. പകരം ഈ ഭാഗങ്ങൾ യാഗവിധിയുമായി (കർമ്മം) അന്തർലീനമായി ബന്ധപ്പെട്ടിരിക്കുന്നു. കല്പിക്കപ്പെടുന്ന ധാർമ്മിക പ്രവൃത്തിയെ സ്തുതിക്കാനോ പ്രോത്സാഹിപ്പിക്കാനോ സന്ദർഭമൊരുക്കാനോ മാത്രമാണ് അവയുടെ ഏക ഉദ്ദേശ്യം. വേദത്തിലെ ഓരോ അക്ഷരവും ശാശ്വതമാണ്, ഓരോ അക്ഷരവും ആത്യന്തികമായി ധർമ്മത്തെ സേവിക്കുന്നു.",
