    "iast": "",
    "conceptIds": [
      "arthavada"
    ],
    "translation": "(ഒന്നിനെ മറ്റൊന്നായി തിരിച്ചറിയുന്നത്) രൂപങ്ങളുടെ ബാഹുല്യം അഥവാ പ്രവർത്തനസാമ്യം കൊണ്ടാണ്.",
    "commentary": "ഗ്രന്ഥം 'യജമാനൻ പ്രസ്തരമാണ് (പുണ്യപ്പുല്ല് കെട്ട്)' എന്ന് പറയുന്നതിനെ എതിരാളി എതിർത്തു. ജൈമിനി ഈ ഗുണവാദം വിശദീകരിക്കുന്നു. യജമാനൻ വ്യക്തമായും മനുഷ്യനാണ്, പുല്ലല്ല. എന്നാൽ പുല്ല്കെട്ട് ആചാരോപകരണങ്ങൾ വെക്കുന്ന ഭൗതിക അടിസ്ഥാനമാകുന്നതുപോലെ, മാനുഷിക യജമാനൻ മുഴുവൻ യാഗത്തിന്റെയും സാമ്പത്തികവും ആത്മീയവുമായ അടിസ്ഥാനമാണ്. രൂപകം അവന്റെ അടിസ്ഥാനപരമായ പങ്കിനെ ആദരിക്കുന്നു.",
