    "translation": "ചരിത്രപരമായി അസാധ്യമായവയെ പരാമർശിക്കുന്നത് പ്രവൃത്തിയുടെ പരമോന്നതത്വം ചിത്രീകരിക്കാനാണ്.",
    "commentary": "'പ്രജാപതി സ്വന്തം ഓമന്റം മുറിച്ചു' എന്ന എതിർവാദത്തെ (1.2.6-ൽ നിന്ന്) അഭിസംബോധനം ചെയ്യുന്നു. ചരിത്രപാഠമോ സ്വയംഹാനിക്കുള്ള അക്ഷരാർത്ഥ കല്പനയോ അല്ലെന്ന് ജൈമിനി പറയുന്നു. ആചാര ഹവിസ്സ് എത്ര അഗാധമായി പ്രധാനമാണെന്ന് കാട്ടാനുള്ള തീവ്രവും പൗരാണികവുമായ അർത്ഥവാദമാണിത് — സ്രഷ്ടാവ് തന്നെ സ്വന്തം സത്ത ബലി നൽകി. മാനുഷിക പുരോഹിതനിൽ നിന്ന് പൂർണ്ണ സമർപ്പണം ആവശ്യപ്പെടുന്നു.",
