    "devanagari": "",
    "iast": "",
    "conceptIds": [
      "arthavada"
    ],
    "translation": "അവയുടെ പ്രധാന പ്രവർത്തനം കർത്താവിൽ പ്രേരണ (പ്രരോചന) ഉണ്ടാക്കലാണ്.",
    "commentary": "അർത്ഥവാദ അധികരണത്തിന്റെ അവസാനം അടയാളപ്പെടുത്തുന്നു. ആചാരങ്ങൾ ദുഷ്കരവും ചെലവേറിയതും സമയമെടുക്കുന്നതുമാണ് — ഫലങ്ങൾ (സ്വർഗ്ഗം) അദൃശ്യവുമാണ്. കഠിനമായ ജോലികൾ ഏറ്റെടുക്കാൻ മനുഷ്യർക്ക് മാനസിക പ്രേരണ ആവശ്യമാണ്. അർത്ഥവാദങ്ങൾ ഈ 'പ്രരോചന' (പ്രലോഭനം/മഹത്വവൽക്കരണം) നൽകുന്നു — ധർമ്മത്തിന്റെ യാന്ത്രികതയ്ക്ക് ഒഴിച്ചുകൂടാനാവാത്ത മാനസിക എഞ്ചിനായി.",
