    "iast": "",
    "conceptIds": [
      "gunavada"
    ],
    "translation": "(സിദ്ധാന്തം): എന്നാൽ അത് അനാവശ്യമല്ല — കാരണം പുനരുക്തി പുതിയ ഉപകരണ വിശദാംശത്തിന് (ഗുണം) വേണ്ടിയാണ്.",
    "commentary": "വേദം ഉദ്ദേശ്യമില്ലാതെ ആവർത്തിക്കുന്നില്ലെന്ന് പറഞ്ഞ് ജൈമിനി മറുപടി നൽകുന്നു. അറിയപ്പെടുന്ന യാഗം പരാമർശിക്കപ്പെട്ടാൽ അത് 'അനുവാദം' ആണ് — പുതിയ നിർദ്ദേശത്തിന് വിഷയമായി പ്രവർത്തിക്കുന്നു. പഴയ ആചാരത്തെ പുതിയ ഉപകരണം ചേർക്കാനുള്ള വ്യാകരണ ആധാരമായി കൊണ്ടുവരുന്നു മാത്രമാണ് ഗ്രന്ഥം ചെയ്യുന്നത് — പ്രത്യേക തരം കരണ്ടി, പ്രത്യേക മന്ത്രം, ദ്വിതീയ ദേവത പോലെ. പുനരുക്തി പുതിയതിലേക്കുള്ള പാലമാണ്.",
