    "translation": "അഥവാ, നിർവ്വഹണത്തിന്റെ ക്രമം സൂചിപ്പിക്കാനാകാം.",
    "commentary": "അനുവാദത്തിന് (ആവർത്തനം) മൂന്നാം സാധുവായ കാരണം: ആചാരങ്ങളിൽ നൂറുകണക്കിന് സൂക്ഷ്മഘട്ടങ്ങൾ ഉൾപ്പെടുന്നു. പൊതുവായി വിധിക്കപ്പെട്ട പ്രവൃത്തി പുനരുക്തമാക്കുന്നതിലൂടെ, ഇപ്പോഴത്തെ ആചാരസന്ദർഭത്തിൽ വളരെ പ്രത്യേക കാലക്രമത്തിൽ ആ പ്രവൃത്തിയെ ഉറപ്പിക്കുന്നു. 'X ചെയ്ത് (പുനരുക്തി) Y ചെയ്യുക (പുതിയ കല്പന).'",
