    "translation": "അഥവാ, നിയന്ത്രണത്തിന് (നിയമം) വേണ്ടിയാകാം.",
    "commentary": "നാലാം കാരണം: പ്രവൃത്തി ചെയ്യാൻ പല സാധ്യമായ രീതികൾ ഉണ്ടാകാം. ഒരു പ്രത്യേക രീതിയോടെ പ്രവൃത്തി പുനരുക്തമാക്കി വേദം പുരോഹിതനെ മറ്റ് ബദലുകളിൽ നിന്ന് 'നിയന്ത്രിച്ച്' (നിയമം) നിർത്തുന്നു. ആവർത്തനം യഥാർത്ഥ വിശാല കല്പനയുടെ പരിധി ചുരുക്കുന്നു.",
