    "translation": "ഏക പ്രവൃത്തിയെക്കുറിച്ച് ബഹുത്വത്തിൽ പറയുമ്പോൾ അത് അതിന്റെ ഉപകരണ വിശദാംശങ്ങളുടെയോ നിർവ്വഹിക്കുന്നവരുടെയോ ബാഹുല്യത്തെ സൂചിപ്പിക്കുന്നു.",
    "commentary": "ഒരു പ്രത്യേക ആചാരത്തെക്കുറിച്ച് ഗ്രന്ഥം ബഹുവചനത്തിൽ ('അവർ യാഗങ്ങൾ ചെയ്യുന്നു') സംസാരിച്ചാൽ, സംഭവത്തിന്റെ ഏകത്വത്തിന് വിരുദ്ധമല്ല. ബഹുവചനം ഉൾപ്പെട്ട നിരവധി പുരോഹിതരെയോ ആ ഒറ്റ സംഭവത്തിനിടയിലെ നിരവധി ഉപഹവിസ്സുകളെയോ അംഗീകരിക്കുന്നു.",
