    "translation": "ഇങ്ങനെ പുനരുക്തി എപ്പോഴും ഉദ്ദേശ്യപൂർവ്വമാണ് — വിശദാംശം വിധിക്കാനോ ക്രമം സൂചിപ്പിക്കാനോ പ്രയോഗം നിയന്ത്രിക്കാനോ സ്തുതിക്കാനോ സേവിക്കുന്നു.",
    "commentary": "ഈ ഉപവിഭാഗം സമാപിച്ച് ജൈമിനി പറയുന്നു. വ്യാഖ്യാന നിയമം പരമമാണ്: വേദത്തിൽ പൂജ്യം ആവർത്തനമില്ല. എല്ലാ പ്രത്യക്ഷ ആവർത്തനവും (അനുവാദം) പുതിയ നിയമം അവതരിപ്പിക്കാനോ സമയക്രമം നടപ്പാക്കാനോ പരിശീലകനെ മാനസികമായി തയ്യാറാക്കാനോ രൂപകല്പന ചെയ്ത വളരെ കാര്യക്ഷമമായ വ്യാകരണ വാഹനമാണ്. വേദഗ്രന്ഥത്തിന്റെ പൂർണ്ണത നിലനിർത്തപ്പെടുന്നു.",
