    "translation": "(സിദ്ധാന്തം): എന്നാൽ അത് വെറും സ്തുതി മാത്രമാണ് — കാരണം ധർമ്മത്തെക്കുറിച്ചുള്ള അറിവ് പൂർണ്ണമായും പദത്തെ മാത്രം ആശ്രയിച്ചിരിക്കുന്നു.",
    "commentary": "മാനുഷിക യുക്തികൊണ്ട് വേദകല്പനകളെ ന്യായീകരിക്കാമെന്ന ആശയം ജൈമിനി തീർത്തും തള്ളുന്നു. ധർമ്മം അറിയപ്പെടുന്നത് വേദവിധിയിലൂടെ മാത്രമാണ് (1.1.2). 'അതുകൊണ്ട് ഭക്ഷണം തയ്യാറാക്കുന്നു' എന്നതാണ് പാത്രം ഉപയോഗിക്കാനുള്ള യഥാർത്ഥ ബന്ധിപ്പിക്കുന്ന കാരണമെങ്കിൽ, ഭക്ഷണം തയ്യാറാക്കുന്ന ചട്ടി ഉപയോഗിച്ചും വേദം പാലിക്കാമെന്ന് ആർക്കും അവകാശപ്പെടാം. കർശനമായ ആചാരനിയമത്തിന്റെ നാശം തടയാൻ 'കാരണം' സ്തുതിയായിരിക്കണം.",
