    "translation": "(എതിരാളി പറയുന്നു): മന്ത്രങ്ങൾ അർത്ഥം നൽകാൻ ഉദ്ദേശിച്ചുള്ളവയല്ല — കാരണം അവയുടെ അക്ഷരാർത്ഥം സ്ഥാപിത വസ്തുതകൾക്ക് വിരുദ്ധമാണ്.",
