    "commentary": "മന്ത്രങ്ങളിൽ 'അദിതി എല്ലാമാണ്; അവൾ ആകാശവും പിതാവും പുത്രനുമാണ്' പോലുള്ള വരികളുണ്ട്. ഒരേ അസ്തിത്വത്തിന് ഒരേസമയം ആകാശവും പിതാവും ആകില്ലെന്ന് എതിരാളി കുറിക്കുന്നു. അർത്ഥം അരാജകമാണ്.",
