    "translation": "(സിദ്ധാന്തം): എന്നാൽ ഇവിടെയും സാധാരണ ഭാഷയിലെയും പദങ്ങളുടെ അർത്ഥത്തിൽ വ്യത്യാസമില്ല.",
    "commentary": "പ്രതിരോധം തുടങ്ങി അടിസ്ഥാന വ്യാഖ്യാന നിയമം ജൈമിനി പ്രഖ്യാപിക്കുന്നു: വേദപദങ്ങളും വ്യാകരണവും സാധാരണ മാനുഷിക ഭാഷയെപ്പോലെ തന്നെ പ്രവർത്തിക്കുന്നു. ഗ്രാമത്തിൽ മഞ്ഞക്കറയുള്ള മൃഗമാണ് 'പശു' എങ്കിൽ വേദത്തിലും കൃത്യം അതേ അർത്ഥം തന്നെയാണ്. മന്ത്രങ്ങൾ തീർച്ചയായും അർത്ഥം നൽകുന്നു.",
