    "commentary": "1.2.32-ന് മറുപടി. മന്ത്രത്തിൽ പര്യായങ്ങൾ ഉപയോഗിക്കാനാവില്ലെന്ന് ജൈമിനി സമ്മതിക്കുന്നു. എന്നാൽ ഇതിനർത്ഥം പദങ്ങൾക്ക് അർത്ഥമില്ലെന്നല്ല! അർത്ഥമാണ് പ്രാഥമിക ധർമ്മം — എന്നാൽ ആചാരത്തിന്റെ ആത്മീയ ബാറ്ററി ചാർജ് (അദൃഷ്ടം) ഉണ്ടാക്കാൻ കൃത്യമായ ശബ്ദക്രമം കൂടുതൽ നിയന്ത്രണമാണ് (നിയമം). അർത്ഥവും ശബ്ദവും പ്രധാനമാണ്.",
