    "commentary": "1.2.33-ന് മറുപടി. പുല്ലിനോടോ കല്ലുകളോടോ സംസാരിക്കുന്നത് ആചാരസന്ദർഭത്തിൽ അവയുടെ പ്രാധാന്യം ഉയർത്താനുള്ള സാഹിത്യ ഉപകരണമാണ്. ധർമ്മത്തിന്റെ ഉപകരണങ്ങളോടുള്ള ആദരവ് കാട്ടുന്നു.",
