    "iast": "",
    "conceptIds": [
      "bhavana"
    ],
    "translation": "(എതിരാളി പറയുന്നു): ധർമ്മം വേദത്തെ (ശബ്ദത്തെ) മാത്രം മൂലമാക്കിയതിനാൽ, വേദമല്ലാത്തത് (സ്മൃതി) അവഗണിക്കണം.",
    "commentary": "സ്മൃതി അധികരണം ആരംഭിക്കുന്നു. 'സ്മൃതി' എന്നത് മനുഷ്യർ രചിച്ച ഗ്രന്ഥങ്ങളെ (മനുസ്മൃതി പോലെ) സൂചിപ്പിക്കുന്നു. 1.1.2-ലെ ജൈമിനിയുടെ സ്വന്തം നിയമം എതിരാളി ഉപയോഗിക്കുന്നു: ശാശ്വതവും കർത്താവില്ലാത്തതുമായ വേദം മാത്രം ധർമ്മം വെളിപ്പെടുത്തുന്നതിനാൽ, മനുഷ്യരചിതമായ ഗ്രന്ഥങ്ങൾ തെറ്റുപറ്റാവുന്നവയും ധർമ്മകാര്യങ്ങളിൽ അധികാരമില്ലാത്തവയുമാണ്.",
