    "commentary": "അനുമാനയുക്തികൊണ്ട് ജൈമിനി സ്മൃതിയെ പ്രതിരോധിക്കുന്നു. സ്മൃതികൾ എഴുതിയ പുരാതന ഋഷിമാർ (മനു പോലെ) വേദങ്ങൾ കുറ്റമറ്റ രീതിയിൽ മനഃപാഠമാക്കിയ അതേ ആളുകൾ തന്നെയാണ്. ഇപ്പോഴുള്ള വേദശാഖകളിൽ കാണാത്ത നിയമം മനു എഴുതിയാൽ, നമുക്ക് നഷ്ടപ്പെട്ട വേദശാഖയിൽ അദ്ദേഹം അത് വായിച്ചുവെന്ന് യുക്തിപൂർവ്വം അനുമാനിക്കുന്നു. അതിനാൽ സ്മൃതിക്ക് പരോക്ഷ അധികാരമുണ്ട്; വേദം പോലെ അനുസരിക്കപ്പെടുന്നു.",
