    "commentary": "ഹേതുദർശനാധികരണമാണിത്. 'യജമാനൻ തന്റെ മുഴുവൻ സ്വത്തും പുരോഹിതന് നൽകണം' എന്ന് മാനുഷിക ഗ്രന്ഥം നിയമമുണ്ടാക്കിയാൽ മീമാംസ തള്ളുന്നു. എന്തുകൊണ്ട്? വ്യക്തമായ ലൗകിക ഉദ്ദേശ്യം (മാനുഷിക അത്യാഗ്രഹം) കാണാം. മാനുഷിക കർത്താവ് നിയമം കെട്ടിച്ചമയ്ക്കാൻ സ്വാർത്ഥ കാരണമൊന്നും ഇല്ലെങ്കിൽ മാത്രമേ നഷ്ടപ്പെട്ട വേദഗ്രന്ഥത്തെ അനുമാനിക്കൂ.",
