    "translation": "(എതിരാളി പറയുന്നു): കല്പസൂത്രങ്ങൾ (ആചാര നിർവ്വഹണ മാന്വലുകൾ) യാഗങ്ങളുടെ വിശദാംശങ്ങൾ നേരിട്ട് പഠിപ്പിക്കുന്നതിനാൽ വേദം പോലെ സ്വതന്ത്ര അധികാരമുള്ളതായി കണക്കാക്കണം.",
