    "translation": "(സിദ്ധാന്തം): അല്ല, അവ വെറും സ്മൃതികളാണ് (ഓർമ്മകൾ) — കാരണം അവയുടെ മാനുഷിക കർത്താക്കൾ അറിയപ്പെടുകയും ഓർമ്മിക്കപ്പെടുകയും ചെയ്യുന്നു.",
