    "number": "I.3.14",
    "section": "Adhyaya 1, Pada 3 (Smriti & Custom)",
    "devanagari": "",
    "iast": "",
    "conceptIds": [
      "smriti"
    ],
    "translation": "They are composed merely to simplify the practical execution of the highly complex rites for the priests. [Prayogārtham...]",
