    "commentary": "നാമം ('അരി', 'പശു', 'തീ' പോലെ) നിശ്ചലവും നിലവിലുള്ളതുമായ അസ്തിത്വത്തെ സൂചിപ്പിക്കുന്നു. നാമത്തെ 'ചെയ്യാൻ' കഴിയില്ല. അതിനാൽ വേദത്തിലെ നാമങ്ങൾ ധർമ്മം കല്പിക്കുന്നില്ല; പ്രധാന പ്രവൃത്തി നിർവ്വഹിക്കാൻ ആവശ്യമായ ഉപകരണങ്ങളോ ദ്രവ്യങ്ങളോ ആയി ഘടനാപരമായ ഉദ്ദേശ്യം മാത്രം നിറവേറ്റുന്നു.",
