    "iast": "",
    "conceptIds": [
      "sankhya"
    ],
    "translation": "If a text enjoins a totally different, incompatible material (like liquid whey instead of solid curds) for the same apparent offering, the action is split into two. [Guṇa-virodhāt ca...]",
