    "translation": "രണ്ട് ദ്രവ്യങ്ങൾ പറയപ്പെടുമ്പോൾ പ്രവൃത്തിയുമായി ഭൗതികമായി ബന്ധപ്പെട്ടത് പ്രധാനമാണ്.",
    "commentary": "തൈര് തീയെ സ്പർശിച്ച് ദഹിക്കുന്നു — അർപ്പിക്കുക എന്ന ക്രിയയെ നേരിട്ട് നിറവേറ്റുന്നു. കോപ്പ തൈര് പിടിക്കുന്നു മാത്രമാണ്. അതിനാൽ തൈര് പ്രധാന ദ്രവ്യവും കോപ്പ ഉപകരണവുമാണ്.",
