    "devanagari": "",
    "iast": "",
    "conceptIds": [
      "adhikara-bheda"
    ],
    "translation": "Regarding the Āveṣṭi, since it is an independent act, the specific reward mentioned for it (food/prosperity) is also independently attainable. [Svataṇtra-phalatvāt...]",
