    "section": "Adhyaya 2, Pada 3 (Variations & Option)",
    "devanagari": "",
    "iast": "",
    "conceptIds": [
      "adhikara-bheda"
    ],
    "translation": "While a Brāhmaṇa performing it independently reaps its specific, isolated reward (food/prosperity). [Brāhmaṇasya pṛthak...]",
